package com.gathin.tvhome;
/** Shared semantic symbols for native settings cards and labels. */
final class MenuIcon {
 static String of(String title){String s=title.toLowerCase(java.util.Locale.GERMAN);if(s.contains("pin")||s.contains("sperr")||s.contains("code"))return "lock";if(s.contains("ton")||s.contains("cec")||s.contains("lautst"))return "volume";if(s.contains("wetter")||s.contains("weather"))return "cloud";if(s.contains("sleep")||s.contains("timer")||s.contains("zeit"))return "timer";if(s.contains("schoner")||s.contains("ruhe"))return "moon";if(s.contains("video")||s.contains("live")||s.contains("kanal")||s.contains("content"))return "video";if(s.contains("bild")||s.contains("hintergrund")||s.contains("farbe")||s.contains("verlauf"))return "photo";if(s.contains("dock"))return "dock";if(s.contains("cpu")||s.contains("ram")||s.contains("widget")||s.contains("system"))return "cpu";if(s.contains("speicher"))return "storage";if(s.contains("focus")||s.contains("fokus")||s.contains("glanz")||s.contains("effekt"))return "star";if(s.contains("position")||s.contains("verschieb")||s.contains("navigation"))return "move";if(s.contains("app")||s.contains("pack")||s.contains("raster")||s.contains("layout"))return "grid";if(s.contains("sichtbar")||s.contains("vorschau")||s.contains("anzeigen"))return "eye";return "tune";}
}
